import{t as e}from"./utils-COoNfFoj.js";var t={slug:`gabe-harris`,influencerName:`Gabe Harris`,influencerHandle:`@watch.gabe`,influencerAvatarUrl:`${e}/gabe-harris-avatar.png`,multiAsset:!0,heroTitle:`Gabe's Computer Builds`,assets:[{title:`B-Roll Shot List Builder`,imageUrl:`${e}/gabe-harris-b-roll-shot-list-builder.png`,quote:`I built a tool that gives you instant angles and ideas when you’re trying to shoot B-roll in a new location. This becomes your go-to B-roll shot list builder anytime the creative juices aren’t flowing.`,promptText:`Act as a cinematographer: design 8 distinct B-roll angles for the scene I describe, then render each as a photorealistic still. I’ll provide a selfie for likeness, 3–5 photos of my location, and one reference image that sets the mood and color grade. Mix wide, medium, and tight framings, and draw from angles like overhead, POV, over-the-shoulder, low-angle profile, and macro details — plus any others that fit the scene. Caption each render with camera position, lens, movement, and lighting notes.`,remixUrl:`https://www.perplexity.ai/computer/a/fscreative-shot-list-builder-Bzuy1pQaQI6ssBiDpJEagg`},{title:`Social Media Content Dashboard`,imageUrl:`${e}/gabe-harris-social-media-content-dashboard.png`,quote:`I built a content dashboard that tracks all of my analytics and engagement across Instagram, YouTube, ManyChat, and my email platform. It shows exactly how many times I’ve included a CTA in my content — and how often those CTAs are actually triggered. It also sends a weekly snapshot every Monday at 9 a.m., so I always know what’s working.`,promptText:`Build a single-page content analytics dashboard (Node + SQLite + static HTML/CSS/JS) that ingests CTA webhook events plus Instagram and YouTube post data, with a sticky header, time-range tabs (7d/30d/90d/all), a totals bar, stat cards with sparklines, an expandable CTA performance table, a top-posts grid, a posting heatmap, and a heuristic insights card surfacing what’s working, what’s not, and what to do next. Use a clean editorial look — Satoshi body, JetBrains Mono for numbers, warm terracotta accent (#c2410c), light mode — and expose JSON endpoints (/api/overview, /api/insights, /api/top-posts) so it can extend later to a monthly calendar and a scheduled-content pipeline view. No login screen by default.`,remixUrl:`https://gabe-cta-logger.pplx.app/`},{title:`Walk & Talk Email Automation`,imageUrl:`${e}/gabe-harris-walk-talk-email-automation.png`,quote:`I built a system that lets me go on a morning walk and talk through an idea off the cuff. AI turns that idea into a fully written email, which I can review and approve inside without leaving the Perplexity app. From there, it broadcasts the email directly through ConvertKit — removing all the friction from writing, formatting, and scheduling, so I can focus on sharing consistently.`,promptText:`I want to build a full email studio for ConvertKit inside Perplexity. I share an idea by voice or text, have it drafted in my brand voice and styled as production-ready HTML with highlight colors, bold emphasis, block spacing, and on-brand CTA buttons, previewed inline so I can refine it conversationally. Then Perplexity connects to my ConvertKit account and schedules or sends the broadcast directly from the thread.`,remixUrl:`https://www.perplexity.ai/computer/a/fscreative-studio-Bcj7O21RSRery31NnliXxg`}]};export{t as default};
